import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 31 咸：感应不是操控至读后比较与自测","description":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","frontmatter":{"title":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 31 咸：感应不是操控至读后比较与自测","description":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","splitFrom":"life/personal/yijing/hexagrams-25-32.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","summary":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰","link":"/life/personal/yijing/hexagrams-25-32-part-02"},"next":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","link":"/life/personal/yijing/hexagrams-33-40"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰","link":"/life/personal/yijing/hexagrams-25-32-part-02"},"next":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","link":"/life/personal/yijing/hexagrams-33-40"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-25-32-part-03.md","filePath":"life/personal/yijing/hexagrams-25-32-part-03.md"}'),i={name:"life/personal/yijing/hexagrams-25-32-part-03.md"};function o(s,t,l,d,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读四-无妄大畜颐大过至坎离咸恒-·-31-咸-感应不是操控至读后比较与自测" tabindex="-1">六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 31 咸：感应不是操控至读后比较与自测 <a class="header-anchor" href="#六十四卦详读四-无妄大畜颐大过至坎离咸恒-·-31-咸-感应不是操控至读后比较与自测" aria-label="Permalink to &quot;六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 31 咸：感应不是操控至读后比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-25-32">返回分篇目录</a></p><p>本组先读无妄与大畜，再看颐的养、大过的承载极限，随后以坎离结束上经、以咸恒开启下经。上下经的划分不等于“上经只有天道、下经只有人事”：孔颖达在咸卦疏中已经讨论并反对这种过度割裂，因为每个六爻卦都兼涉天地人。</p><p>本文逐卦实际查阅《周易》经传与《周易正义》卷三、卷四对应篇。原文保留古字、繁体，简体解释为本篇概括；疑难处并列读法，不将古注当成唯一译文。大畜“曰閑輿衛”、坎“樽酒簋貳”、离“大耋之嗟”、恒“振恒”等参照《正义》录文，其他页面可能有异体或异文。古籍中的吉凶、疾病与灾害语句不构成现代预测或诊疗依据。</p><h2 id="gua-31" tabindex="-1">31 咸：感应不是操控 <a class="header-anchor" href="#gua-31" aria-label="Permalink to &quot;31 咸：感应不是操控 {#gua-31}&quot;">​</a></h2><p><strong>卦符：䷞　上卦：兑 ☱（泽、悦）　下卦：艮 ☶（山、止）。</strong></p><p><strong>卦辞原文</strong>：咸：亨，利貞，取女吉。</p><p><strong>白话概括</strong>：咸从感理解，卦辞以婚姻为主要场景，取女即娶女。《正义》强调二气相与、男女相感，并非一方独自发动即可成关系。古代婚姻制度与今日不同，但相互响应、保持正当的层次可以继续讨论；不能把咸读成让别人爱上自己的操控术。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：咸其拇。</td><td>感应先及脚拇，尚处轻微发动阶段。经文未标吉凶，不必给每一个微小感受添上确定结果。</td></tr><tr><td>六二：咸其腓，凶，居吉。</td><td>小腿欲动而轻随，可能有险；先安处则吉。感到冲动与立刻行动并非一回事。</td></tr><tr><td>九三：咸其股，執其隨，往吝。</td><td>大腿随身体运动，借以表现执着跟随。失去自身判断，贸然前往便困窘。</td></tr><tr><td>九四：貞吉悔亡，憧憧往來，朋從爾思。</td><td>守正可吉，若心思往来不定、只求他人跟随自己的想法，感通便不够广大。憧憧不是纯粹浪漫思念。</td></tr><tr><td>九五：咸其脢，无悔。</td><td>感于背脊一带的肉，古注对其距离心志、影响范围有不同说明；虽无悔，却未必是最充分的感通。</td></tr><tr><td>上六：咸其輔，頰，舌。</td><td>感应停在口颊舌头，偏重言说。《小象》警惕腾口说，提醒不能把漂亮话当作关系的全部。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“山上有澤，咸；君子以虛受人。”</p><p><strong>解释</strong>：山上有泽，借虚处能容说明接受他人。虚受不是没有立场，而是暂不被自己的预断填满，允许对方真实表达；关系是否继续还需双方自主选择。</p><p><strong>整体读法与误区</strong>：身体意象从拇、腓、股移向脢、口，并不简单等于一条越来越成功的恋爱路线；其中反而多次限制轻动、随人、偏思与空言。卦辞利贞同样适用于相感过程：尊重边界、理解回应比猜测征兆更可靠。“取女吉”不能证明某段婚姻必成，更不能替代当事人的同意。</p><p><strong>细读线索</strong>：咸以艮止在下、兑悦在上，古传同时强调止与悦，说明感应不只是情绪奔涌，也包含停住自己的冲动。初、二、三的身体部位逐步上移，却没有形成吉利递增；四爻虽不明说心，思与往来已转向心意；上六最终落在口说。这个排列可帮助区分身体反应、追随行为、内心执念和语言表达，让读者注意自己说出的热情是否真的得到对方回应。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8" target="_blank" rel="noopener noreferrer">《周易·咸》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E5%92%B8" target="_blank" rel="noopener noreferrer">《周易正义·下经咸传卷四·咸》</a>。</p><h2 id="gua-32" tabindex="-1">32 恒：持久需要变化中的一致 <a class="header-anchor" href="#gua-32" aria-label="Permalink to &quot;32 恒：持久需要变化中的一致 {#gua-32}&quot;">​</a></h2><p><strong>卦符：䷟　上卦：震 ☳（雷、动）　下卦：巽 ☴（风、入）。恒、恆为不同字形。</strong></p><p><strong>卦辞原文</strong>：恆：亨，无咎。利貞，利有攸往。</p><p><strong>白话概括</strong>：恒是长久，但《正义》开篇便指出恒久之道贵在变通，随时变化才可能长久。《彖》以日月、四时为例：四季不断改变，循环之道才能持续。因此恒不等于某个动作永远不改，更不是用坚持为已经证实无效的方式辩护。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：浚恆，貞凶，无攸利。</td><td>刚开始便要求关系或事情达到很深程度，求恒太急反而凶。浚是求深，持久不能靠一次加压获得。</td></tr><tr><td>九二：悔亡。</td><td>简短到只说悔恨消除；《小象》以能久中解释，提示持续的适中比夸张表态重要。</td></tr><tr><td>九三：不恆其德，或承之羞，貞吝。</td><td>德行反复无常，招致羞辱或不信任。不能只要求别人相信，而不保持自己的行为一致。</td></tr><tr><td>九四：田无禽。</td><td>田猎无获，古注以久处非位解释。持续投入若位置、对象或方式不对，并不会自动有收获。</td></tr><tr><td>六五：恆其德，貞，婦人吉，夫子凶。</td><td>古注按妇人从一、男子制义的角色规范区分吉凶。应认识其历史性，不将这种性别分工直接作为今日伦理。</td></tr><tr><td>上六：振恆，凶。</td><td>震动不安、频繁躁动而想求恒，反而不利。振亦作震；这里不是否定必要调整，而是警告无稳定依据的折腾。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“雷風，恆；君子以立不易方。”</p><p><strong>解释</strong>：雷风相与而持续，君子确立所守方向，不轻易改变。方向稳定与措施变通应结合阅读：若把不易方理解成不许更新知识，就与《正义》关于变通的说明相抵触。</p><p><strong>整体读法与误区</strong>：初六求深过早，九三德行不定，九四久而非位，上六躁动不安，都说明“时间很长”不足以证明恒的价值。与<a href="/life/personal/yijing/hexagrams-25-32-part-03#gua-31">咸</a>并读，咸看感应怎样发生，恒看关系如何延续；感应不等于承诺，承诺也需要持续、相互且可以检验的行动。它不要求人在有害关系中无限忍耐。</p><p><strong>细读线索</strong>：恒的卦体与咸不同，震动与巽入相配，彖传又说刚柔皆应，强调关系可以持续响应。可是六爻并没有给出一个全然顺利的长久故事：开始过深、中途失德、久居非位、终端躁动都足以破坏恒。九二只有悔亡两个字，反而突出久中的简明。把这些片段放在一起，可以看到恒所重的是不断维持适当关系，而不是用一次郑重承诺冻结此后所有变化。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92" target="_blank" rel="noopener noreferrer">《周易·恒》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E6%81%92" target="_blank" rel="noopener noreferrer">《周易正义·下经咸传卷四·恒》</a>。</p><h2 id="读后比较与自测" tabindex="-1">读后比较与自测 <a class="header-anchor" href="#读后比较与自测" aria-label="Permalink to &quot;读后比较与自测 {#读后比较与自测}&quot;">​</a></h2><ol><li>无妄六三怎样限制“受灾者一定有错”的判断？初九与上九又怎样限制“只看动机”的判断？</li><li>大畜的止与颐的养有什么联系？为什么不把畜养全部等同于囤积财物？</li><li>大过上六“凶，无咎”是否矛盾？如何区分结果、能力、责任与动机？</li><li>坎的求小得、离的继明，各自反对哪一种不切实际的期待？</li><li>咸的虚受与恒的不易方怎样同时成立？怎样区分有原则的持久和固执？</li></ol><p>前篇：<a href="/life/personal/yijing/hexagrams-17-24">第 17—24 卦：随蛊至剥复</a>。返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',27)])])}const f=e(i,[["render",o]]);export{c as __pageData,f as default};
